        add("display.vrr-configured","display",t("Saved VRR floor","Kayıtlı VRR alt sınırı"),t("Read the saved next-boot numeric policy without changing the driver.","Sürücüyü değiştirmeden sonraki boot için kayıtlı sayısal politikayı okur."),{"display","vrr-min","configured"});
        add("display.vrr-set","display",t("Save next-boot VRR floor","Sonraki boot VRR alt sınırını kaydet"),t("Save a bounded floor for the existing guarded module loader. This does not reboot or immediately change the active module; inspect configured and current values separately.","Mevcut korumalı modül yükleyicisi için sınırlı alt eşik kaydeder. Reboot yapmaz veya etkin modülü hemen değiştirmez; kayıtlı ve mevcut değerleri ayrı inceleyin."),{"display","vrr-min","set","{hz}"},{number("hz",t("Minimum refresh (Hz)","En düşük yenileme (Hz)"),t("The backend also checks the current mode's upper bound; 30–143 is only the accepted numeric input range.","Backend mevcut kipin üst sınırını da denetler; 30–143 yalnız kabul edilen sayısal giriş aralığıdır."),"30",30,143)},Effect::local_file,Access::root,Presentation::terminal,0,"display.vrr-configured");

