        add("flashlight.level","lights",t("Request flashlight brightness","Fener parlaklığı iste"),t("The hardware has two lit steps: 1–99% requests map to 50%, and 100% maps to 100%. Zero means off. No raw current/PWM override is available.","Donanımın iki ışık kademesi vardır: 1–99% istekleri yüzde 50'ye, 100% yüzde 100'e karşılık gelir. Sıfır kapalıdır. Ham akım/PWM geçersiz kılması yoktur."),{"flashlight","set","{percent}"},{number("percent",t("Requested brightness (%)","İstenen parlaklık (%)"),t("Request and applied hardware brightness are separate values.","İstek ile uygulanan donanım parlaklığı ayrı değerlerdir."),"50",0,100)},Effect::device,Access::active_session,Presentation::terminal,0,"flashlight.status");
